    juce::Image fadeEdge (const char* photo, bool acrossX)
    {
        auto edge = decodeImage (photo).convertedToFormat (juce::Image::ARGB);
        juce::Image::BitmapData pixels (edge, juce::Image::BitmapData::readWrite);
        const int end = (acrossX ? pixels.width : pixels.height) - 1;
        for (int y = 0; y < pixels.height; ++y)
            for (int x = 0; x < pixels.width; ++x)
            {
                const int at = acrossX ? x : y;
                const float alpha = juce::jlimit (0.0f, 1.0f, (float) juce::jmin (at, end - at) / 2.5f);
                pixels.setPixelColour (x, y, pixels.getPixelColour (x, y).withAlpha (alpha));
            }
        return edge;
    }

    void drawMainBezel (juce::Graphics& g, juce::Rectangle<int> bounds, float sideWidth)
    {
        static const auto top = fadeEdge (topEdge, false);
        static const auto bottom = fadeEdge (bottomEdge, false);
        static const auto left = fadeEdge (leftEdge, true);
        static const auto right = fadeEdge (rightEdge, true);
        auto area = bounds.toFloat();
        g.setColour (juce::Colours::white);
        g.drawImage (left, area.removeFromLeft (sideWidth));
        g.drawImage (right, area.removeFromRight (sideWidth));
        g.drawImage (top, area.removeFromTop (14.0f).expanded (4.0f, 0.0f).translated (0.0f, -5.0f));
        g.drawImage (bottom, area.removeFromBottom (15.0f).expanded (4.0f, 0.0f));
    }

    struct KnobPhoto
    {
        juce::Image image;
        float pointerAngle, capRatio, diameter, skirtRatio;
    };

    juce::Image softenedKnobPhoto (const char* data)
    {
        auto image = decodeImage (data);
        juce::Image::BitmapData pixels (image, juce::Image::BitmapData::readWrite);
        const auto soften = [] (float value) { return 0.018f + 0.942f * std::pow (value, 0.82f); };
        for (int y = 0; y < pixels.height; ++y)
            for (int x = 0; x < pixels.width; ++x)
            {
                const auto source = pixels.getPixelColour (x, y);
                pixels.setPixelColour (x, y, juce::Colour::fromFloatRGBA (
                    soften (source.getFloatRed()), soften (source.getFloatGreen()),
                    soften (source.getFloatBlue()), source.getFloatAlpha()));
            }
        return image;
    }

    const KnobPhoto& knobPhoto (bool compact, bool selector, bool frequency)
    {
        static const KnobPhoto main { softenedKnobPhoto (ashKnobMain), 2.65f, 0.59f, 56.0f, 0.90f };
        static const KnobPhoto choice { softenedKnobPhoto (ashKnobSelector), -0.33f, 0.46f, 58.0f, 0.96f };
        static const KnobPhoto tuning { softenedKnobPhoto (ashKnobFrequency), 0.0f, 0.67f, 64.0f, 0.91f };
        static const KnobPhoto small { softenedKnobPhoto (ashKnobSmall), -2.45f, 0.58f, 40.0f, 0.91f };
        return compact ? small : (selector ? choice : (frequency ? tuning : main));
    }

    const juce::Image& switchPhoto (bool on, bool vertical, bool blue, bool silver)
    {
        static const auto blueOnPhoto = decodeImage (blueOn);
        static const auto blueOffPhoto = decodeImage (blueOff);
        static const auto amberOnPhoto = decodeImage (amberOn);
        static const auto amberOffPhoto = decodeImage (amberOff);
        static const auto neutralPhoto = decodeImage (neutral);
        static const auto blueVerticalPhoto = decodeImage (blueVertical);
        if (vertical)
            return blueVerticalPhoto;
        if (silver)
            return neutralPhoto;
        return blue ? (on ? blueOnPhoto : blueOffPhoto) : (on ? amberOnPhoto : amberOffPhoto);
    }

    bool drawMockupLabel (juce::Graphics& g, const juce::String& key, juce::Rectangle<int> bounds)
    {
        struct Label { const char* key; juce::Image image; int height; };
        static const Label labels[] {
            { "CONTROLLERS", decodeImage (mockupControllers), 22 },
            { "OSCILLATOR BANK", decodeImage (mockupOscillatorBank), 22 },
            { "MIXER", decodeImage (mockupMixer), 25 },
            { "LOUDNESS CONTOUR", decodeImage (mockupLoudnessContour), 16 },
            { "oscillator1", decodeImage (mockupOsc1), 13 },
            { "oscillator2", decodeImage (mockupOsc2), 13 },
            { "oscillator3", decodeImage (mockupOsc3), 13 },
            { "RANGE", decodeImage (mockupRange), 11 },
            { "WAVEFORM", decodeImage (mockupWaveform), 11 },
            { "FREQUENCY", decodeImage (mockupFrequency), 11 },
            { "CUTOFF", decodeImage (mockupCutoff), 18 },
            { "EMPHASIS", decodeImage (mockupEmphasis), 12 },
            { "CONTOUR AMT", decodeImage (mockupContour), 18 },
            { "ATTACK", decodeImage (mockupAttack), 12 },
            { "decayTime", decodeImage (mockupDecayTime), 12 },
            { "SUSTAIN", decodeImage (mockupSustain), 12 },
            { "DECAY", decodeImage (mockupDecay), 12 },
            { "NOISE", decodeImage (mockupNoise), 13 },
            { "EXTERNAL", decodeImage (mockupExternal), 18 },
            { "outGain", decodeImage (mockupVolume), 12 },
            { "FILTER MOD", decodeImage (mockupFilterMod), 18 },
            { "OSC. 3 CONTROL", decodeImage (mockupOscControl), 18 },
            { "OVERLOAD", decodeImage (mockupOverload), 10 },
            { "MOD AMOUNT", decodeImage (mockupModAmount), 18 },
            { "MOD MIX", decodeImage (mockupModMix), 18 },
        };
        const auto label = std::find_if (std::begin (labels), std::end (labels),
                                         [key] (const auto& candidate) { return key == candidate.key; });
        if (label == std::end (labels))
            return false;

        g.setColour (juce::Colours::white);
        g.drawImage (label->image, bounds.withSizeKeepingCentre (bounds.getWidth(), label->height).toFloat(),
                     juce::RectanglePlacement::centred);
        return true;
    }

    juce::Font panelFont (float size, bool bold = true, float kerning = 0.0f)
    {
        static const auto face = []
        {
            juce::MemoryOutputStream bytes;
            juce::Base64::convertFromBase64 (bytes, panelFontData);
            return juce::Typeface::createSystemTypefaceFor (bytes.getData(), bytes.getDataSize());
        }();
        const auto options = face != nullptr ? juce::FontOptions (face).withHeight (size)
                                             : juce::FontOptions (size, bold ? juce::Font::bold : juce::Font::plain);
        return juce::Font (options).withExtraKerningFactor (kerning * 0.35f);
    }

    juce::Font monoFont (float size)
    {
        return juce::Font (juce::FontOptions (juce::Font::getDefaultMonospacedFontName(), size, juce::Font::plain));
    }

    constexpr int referenceWidth = 1400, editorW = 1480, editorH = 634, cheekW = 26;
    constexpr int referencePanelTop = 64, referencePanelHeight = 461;
    constexpr int panelTop = 56, panelHeight = 426;
    constexpr int setupHeight = 112, setupGap = (editorH - panelTop - panelHeight - setupHeight) / 2;
    constexpr int auxiliaryColumns = 11, auxiliaryRowHeight = 112;

    int panelX (int x)
    {
        return cheekW + juce::roundToInt ((x - cheekW) * (editorW - 2.0f * cheekW) / (referenceWidth - 2.0f * cheekW));
    }

    int panelY (int y)
    {
        return panelTop + juce::roundToInt ((y - referencePanelTop) * (float) panelHeight / referencePanelHeight);
    }

    juce::Rectangle<int> mainPanelBounds (juce::Rectangle<int> reference)
    {
        const int left = panelX (reference.getX());
        return { left, panelY (reference.getCentreY()) - reference.getHeight() / 2, panelX (reference.getRight()) - left, reference.getHeight() };
    }
